export const ECOMMERCE_PLATFORM_PART2_MARKDOWN = "# Performance Optimization Strategies (Part 2)\n\nPerformance in e-commerce directly impacts revenue. This part focuses on **rendering strategy**, **streaming**, **assets**, and **caching** patterns that improve Core Web Vitals without making the codebase hard to evolve.\n\nPart 1: [Architecture & Foundation](/blog/ecommerce-platform)\n\n---\n\n## Rendering Strategy Decision Matrix\n\nDifferent page types require different rendering strategies:\n\n| Page type      | Strategy        | Rationale                              | Revalidation |\n| -------------- | --------------- | -------------------------------------- | ------------ |\n| Homepage       | ISR             | High traffic, moderate updates         | 60s          |\n| Category pages | ISR             | Frequent visits, periodic updates      | 120s         |\n| Product pages  | ISR + Streaming | SEO critical, some sections can stream | 300s         |\n| Search results | SSR             | Dynamic + user-specific                | N/A          |\n| Cart           | Client-side     | Highly interactive                     | N/A          |\n| Checkout       | SSR             | Security + server validation           | N/A          |\n| Account pages  | SSR             | Private + user-specific                | N/A          |\n| Static content | SSG             | Rarely changes                         | Build time   |\n\n---\n\n## Incremental Static Regeneration (ISR)\n\nISR gives you fast static delivery with freshness. Category and listing pages are usually the best fit.\n\n### Product listing implementation\n\n```ts\n// app/categories/[slug]/page.tsx\nimport { Suspense } from \"react\";\n\n// Revalidate every 2 minutes\nexport const revalidate = 120;\n\nexport async function generateStaticParams() {\n  const topCategories = await getTopCategories(20);\n\n  return topCategories.map((category) => ({\n    slug: category.slug,\n  }));\n}\n\nexport async function generateMetadata({\n  params,\n}: {\n  params: { slug: string };\n}) {\n  const category = await getCategory(params.slug);\n\n  return {\n    title: `${category.name} | Your Store`,\n    description: category.description,\n    openGraph: {\n      title: category.name,\n      description: category.description,\n      images: [category.image],\n    },\n  };\n}\n\nexport default async function CategoryPage({\n  params,\n  searchParams,\n}: {\n  params: { slug: string };\n  searchParams: { sort?: string; price?: string };\n}) {\n  const category = await getCategory(params.slug);\n\n  const filters = {\n    categoryId: category.id,\n    sort: searchParams.sort || \"popularity\",\n    priceRange: searchParams.price ? parsePriceRange(searchParams.price) : null,\n  };\n\n  return (\n    <div className=\"category-page\">\n      <CategoryHeader category={category} />\n\n      <div className=\"category-content\">\n        <aside className=\"filters\">\n          <Filters categoryId={category.id} />\n        </aside>\n\n        <main>\n          {/* Stream product grid for faster TTI */}\n          <Suspense fallback={<ProductGridSkeleton />}>\n            <ProductGrid filters={filters} />\n          </Suspense>\n        </main>\n      </div>\n    </div>\n  );\n}\n```\n\n---\n\n## Product pages: ISR + Streaming\n\nEven if the page is ISR, you can still stream non-critical sections.\n\n```ts\n// app/products/[id]/page.tsx\nimport { Suspense } from \"react\";\nimport { notFound } from \"next/navigation\";\n\nexport const revalidate = 300;\n\nexport async function generateStaticParams() {\n  const topProducts = await getTopProducts(1000);\n\n  return topProducts.map((product) => ({\n    id: product.id,\n  }));\n}\n\nexport default async function ProductPage({\n  params,\n}: {\n  params: { id: string };\n}) {\n  const product = await getProduct(params.id);\n  if (!product) notFound();\n\n  const inventory = await getInventoryStatus(params.id);\n\n  return (\n    <>\n      <ProductSchema product={product} />\n\n      <div className=\"product-page\">\n        <ProductGallery images={product.images} />\n\n        <div className=\"product-info\">\n          <h1>{product.name}</h1>\n          <ProductPrice price={product.price} />\n          <ProductRating rating={product.averageRating} count={product.reviewCount} />\n\n          <AddToCartSection product={product} inventory={inventory} />\n        </div>\n      </div>\n\n      <Suspense fallback={<DescriptionSkeleton />}>\n        <ProductDescription productId={params.id} />\n      </Suspense>\n\n      <Suspense fallback={<SpecsSkeleton />}>\n        <ProductSpecifications productId={params.id} />\n      </Suspense>\n\n      <Suspense fallback={<ReviewsSkeleton />}>\n        <ProductReviews productId={params.id} />\n      </Suspense>\n\n      <Suspense fallback={<RecommendationsSkeleton />}>\n        <RecommendedProducts productId={params.id} />\n      </Suspense>\n    </>\n  );\n}\n```\n\n---\n\n## Advanced caching strategies\n\nA practical commerce app usually ends up with **multi-layer caching**:\n\n- Next.js Data Cache (fast, deployment-local)\n- A shared cache (Redis/Upstash)\n- The database (source of truth)\n\n```ts\n// lib/cache/product-cache.ts\nimport { unstable_cache, revalidateTag } from \"next/cache\";\nimport { Redis } from \"@upstash/redis\";\n\nconst redis = new Redis({\n  url: process.env.REDIS_URL!,\n  token: process.env.REDIS_TOKEN!,\n});\n\nexport async function getProductWithCache(id: string) {\n  const cached = await getCachedProduct(id);\n  if (cached) return cached;\n\n  const redisKey = `product:${id}`;\n  const redisData = await redis.get(redisKey);\n  if (redisData) return redisData;\n\n  const product = await db.product.findUnique({\n    where: { id },\n    include: { images: true, variants: true, category: true },\n  });\n\n  if (product) {\n    await redis.set(redisKey, product, { ex: 300 });\n  }\n\n  return product;\n}\n\nconst getCachedProduct = unstable_cache(\n  async (id: string) => getProductWithCache(id),\n  [\"product\"],\n  {\n    revalidate: 300,\n    tags: (id: string) => [`product-${id}`, \"products\"],\n  },\n);\n\nexport async function invalidateProduct(id: string) {\n  await redis.del(`product:${id}`);\n  revalidateTag(`product-${id}`);\n}\n```\n\n### Request memoization (per render)\n\n```ts\n// lib/cache/memoize.ts\nimport { cache } from \"react\";\n\nexport const getProduct = cache(async (id: string) => {\n  return db.product.findUnique({\n    where: { id },\n    include: { images: true, variants: true },\n  });\n});\n```\n\n### Parallel data fetching\n\n```ts\n// app/products/[id]/page.tsx\nexport default async function ProductPage({ params }: { params: { id: string } }) {\n  const [product, inventory, pricing, relatedProducts] = await Promise.all([\n    getProduct(params.id),\n    getInventory(params.id),\n    getPricing(params.id),\n    getRelatedProducts(params.id, { limit: 4 }),\n  ]);\n\n  return (\n    <div>\n      <ProductHero product={product} pricing={pricing} />\n      <InventoryStatus inventory={inventory} />\n      <RelatedProductsSection products={relatedProducts} />\n    </div>\n  );\n}\n```\n\n---\n\n## Image optimization\n\nFor commerce, images are usually the largest contributor to LCP.\n\n```ts\n// components/products/ProductImage.tsx\nimport Image from \"next/image\";\n\nexport function ProductImage({\n  src,\n  alt,\n  priority = false,\n}: {\n  src: string;\n  alt: string;\n  priority?: boolean;\n}) {\n  return (\n    <Image\n      src={src}\n      alt={alt}\n      width={800}\n      height={800}\n      priority={priority}\n      quality={85}\n      sizes=\"(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 800px\"\n    />\n  );\n}\n```\n\n---\n\n## Edge middleware patterns\n\nMiddleware is great for **lightweight personalization** (currency, locale, experiments), but keep logic minimal.\n\n```ts\n// middleware.ts\nimport { NextResponse } from \"next/server\";\nimport type { NextRequest } from \"next/server\";\n\nexport function middleware(request: NextRequest) {\n  const response = NextResponse.next();\n\n  const country = request.geo?.country || \"US\";\n  const currency = getCurrencyForCountry(country);\n\n  response.cookies.set(\"currency\", currency);\n\n  return response;\n}\n\nexport const config = {\n  matcher: [\"/((?!_next/static|_next/image|favicon.ico).*)\"],\n};\n```\n\n---\n\n## Key takeaways (Part 2)\n\n- Use ISR for high-traffic, frequently revisited pages (home/category)\n- Use SSR for user-specific or sensitive flows (search/checkout/account)\n- Stream below-the-fold sections with Suspense to improve perceived performance\n- Treat caching as an architecture concern: local cache + shared cache + DB\n- Optimize images intentionally: sizes, priority, quality, and correct layout\n\n---\n\n## What’s next\n\nPart 3 will focus on building the **product catalog & dynamic pages** with a clean Server/Client component split and SEO-friendly metadata.\n\nBack to Part 1: [Architecture & Foundation](/blog/ecommerce-platform)\n\n[View Live Demo](https://ecomm-966m.vercel.app/)\n" as const;
